&lt;/li&gt;
&lt;li&gt;
&lt;p id=&quot;p-rc_0734c381941f8825-308&quot; data-path-to-node=&quot;7,3,0&quot;&gt;&lt;span data-path-to-node=&quot;7,3,0,0&quot;&gt;Build, mentor, and lead a high-leverage, globally distributed product design team as these product spaces grow&lt;/span&gt;&lt;span class=&quot;&quot; data-path-to-node=&quot;7,3,0,1&quot;&gt;&lt;sup class=&quot;superscript&quot;&gt;&lt;/sup&gt;&lt;/span&gt;&lt;span data-path-to-node=&quot;7,3,0,2&quot;&gt;.&lt;/span&gt; &lt;/p&gt;
