&lt;p&gt;&lt;span class=&quot;&quot; data-path-to-node=&quot;8,1&quot;&gt;&lt;sup class=&quot;superscript&quot;&gt;&lt;/sup&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul data-path-to-node=&quot;9&quot;&gt;
