&lt;/li&gt;
&lt;li class=&quot;animating&quot;&gt;
&lt;p id=&quot;p-rc_d43766e494550528-522&quot; class=&quot;animating&quot; data-path-to-node=&quot;16,4,0&quot;&gt;&lt;span class=&quot;animating&quot; data-path-to-node=&quot;16,4,0,0&quot;&gt;In-office culinary options to cater to your dietary preferences&lt;/span&gt;&lt;/p&gt;
